function countPartitions(nums, k) {
  const MOD = 1000000007;
  const total = nums.reduce((sum, value) => sum + value, 0);
  if (total < 2 * k) {
    return 0;
  }

  const dp = new Array(k).fill(0);
  dp[0] = 1;
  let all = 1;
  for (const value of nums) {
    all = (all * 2) % MOD;
    for (let sum = k - 1; sum >= value; sum--) {
      dp[sum] = (dp[sum] + dp[sum - value]) % MOD;
    }
  }

  let small = 0;
  for (let sum = 0; sum < k; sum++) {
    small = (small + dp[sum]) % MOD;
  }
  const bad = (2 * small) % MOD;
  return (all - bad + MOD) % MOD;
}

