function countPartitions(nums, k) {
  // Try every assignment of elements to the two groups.
  const n = nums.length;
  let great = 0;
  for (let assignment = 0; assignment < 2 ** n; assignment++) {
    let first = 0;
    let second = 0;
    for (let i = 0; i < n; i++) {
      if (Math.floor(assignment / 2 ** i) % 2 === 1) first += nums[i];
      else second += nums[i];
    }
    if (first >= k && second >= k) great++;
  }
  return great % 1000000007;
}

