function generate(rand, size) {
  const int = m => Math.floor(rand() * m);
  if (size === 'large') {
    const n = 1000;
    const k = 500 + int(501);
    const cap = 1 + int(40);
    const nums = Array.from({ length: n }, () => (rand() < 0.05 ? 1 + int(1000000000) : 1 + int(cap)));
    return [nums, k];
  }
  const n = 1 + int(10);
  const cap = rand() < 0.5 ? 5 : 15;
  const nums = Array.from({ length: n }, () => (rand() < 0.08 ? 1000000000 - int(3) : 1 + int(cap)));
  const total = nums.reduce((a, b) => a + b, 0);
  // Pick k near half the total half the time, so the answer is often neither 0 nor 2^n - 2.
  const k = rand() < 0.5 ? Math.max(1, Math.min(1000, Math.floor(total / 2) - int(4))) : 1 + int(30);
  return [nums, k];
}
